/* Parcours relié aux contrats du serveur Crédit PME. */
(()=>{
requests.length=0;docs.length=0;
const M=window.CreditModel;let draft=null;let busy=false;let policies=null;let creditCore='businesses';let creditProfile='reconstructed_cashflows';let creditProduct='equipment';let revocation=[];const draftStore=new Map();
const labels={equipment:'Équipement',working_capital:'Trésorerie',development:'Développement',personal_project:'Projet personnel',housing:'Habitat',education:'Études'};
const statusLabels={favorable:'Favorable',vigilance:'Vigilance',defavorable:'Point de tension',incomplet:'À compléter',non_applicable:'Non applicable'};
const escape=s=>safe(s??'');const format=v=>v===null||v===undefined?'Non disponible':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v);const month=v=>new Intl.DateTimeFormat('fr-FR',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v.length===7?v+'-01':v));
const route=s=>{if(location.hash==='#'+s)window.renderApp();else location.hash=s;window.scrollTo(0,0)};
const steps=f=>['Identité', 'Votre projet',f.core==='individuals'?'Revenus & budget':'Flux de trésorerie','Échéances & dettes',f.core==='individuals'?'Réserve & historique':'Comptabilité & garanties','Hypothèses'];
const fval=k=>escape(draft?.form[k]||'');
function input(key,label,type='text',hint='',required=false){return `<label class="field"><span>${label}${required?' <b>*</b>':''}</span><input data-field="${key}" name="${key}" type="${type}" value="${fval(key)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01" inputmode="decimal"':''} ${type==='email'?'autocomplete="email"':''}><small>${hint}</small></label>`}
function area(key,label,hint='',required=false){return `<label class="field wide"><span>${label}${required?' <b>*</b>':''}</span><textarea data-field="${key}" name="${key}" rows="3" ${required?'required':''}>${fval(key)}</textarea><small>${hint}</small></label>`}
function select(key,label,options){return `<label class="field"><span>${label}</span><select name="${key}" data-field="${key}">${options.map(([value,text])=>`<option value="${value}" ${draft.form[key]===value?'selected':''}>${text}</option>`).join('')}</select></label>`}
function panel(title,subtitle,html){return `<section class="form-panel"><h2>${title}</h2><div class="field-grid">${html}</div></section>`}
function invalidate(){if(!draft)return;draft.reviewState='not_submitted';draft.report=null;draft.revision++}
function sync(form){if(!draft||!form)return;const data=new FormData(form);for(const [key,value] of data){if(key in draft.form)draft.form[key]=value}form.querySelectorAll('[data-period]').forEach(el=>{draft.periods[Number(el.dataset.period)][el.dataset.key]=el.value});form.querySelectorAll('[data-debt]').forEach(el=>{draft.debts[Number(el.dataset.debt)][el.dataset.key]=el.value});form.querySelectorAll('[data-history]').forEach(el=>{draft.history[Number(el.dataset.history)][el.dataset.key]=el.value})}
function setHeading(title,sub,nav){$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===nav));$('.eyebrow').textContent='CRÉDIT PME · VOTRE PARCOURS DE FINANCEMENT';$('#new-request').innerHTML='＋ Nouvelle demande';$('#new-request').onclick=()=>route('choix')}
function rail(stage){const list=[['form','Votre demande'],['documents','Vos documents'],['verification','Vérification'],['analysis','Analyse'],['support','Accompagnement']];const at=list.findIndex(x=>x[0]===stage);return `<div class="journey-rail" aria-label="Étapes du dossier">${list.map(([key,title],i)=>`<div class="rail-item ${i===at?'current':i<at?'done':''}" ${i===at?'aria-current="step"':''}><span>${i<at?'✓':i+1}</span><strong>${title}</strong></div>`).join('')}</div>`}
function modeNotice(){return `<div class="draft-status"><span class="status-dot"></span><span>${draft?.remote?.id?'Dossier enregistré':'Brouillon · non enregistré'}</span></div>`}
function choose(){setHeading('Un projet à vous.\nUn parcours pour avancer.','Choisissez votre profil et ce que vous souhaitez financer.','demande');const business=creditCore==='businesses';$('#view').innerHTML=`<div class="choose-layout"><div><div class="segmented" aria-label="Profil"><button data-core="individuals" class="${!business?'selected':''}">Un particulier</button><button data-core="businesses" class="${business?'selected':''}">Une entreprise / PME</button></div><form id="choice-form" class="choice-form"><label class="field"><span>${business?'Votre organisation financière':'Votre situation professionnelle'}</span><select id="choice-profile">${(business?[['reconstructed_cashflows','Petite activité · flux reconstitués'],['structured_accounts','Entreprise · comptabilité structurée']]:[['employee','Salarié'],['retired','Retraité'],['self_employed','Indépendant']]).map(([v,l])=>`<option value="${v}" ${v===creditProfile?'selected':''}>${l}</option>`).join('')}</select></label><h2>Ce que vous voulez rendre possible.</h2><div class="credit-options">${(business?['equipment','working_capital','development']:['personal_project','housing','education']).map((key,i)=>`<label class="credit-option"><input type="radio" name="product" value="${key}" ${creditProduct===key||(!Object.keys(labels).includes(creditProduct)&&i===0)?'checked':''} required><span class="option-glyph">${['↗','◒','＋'][i]}</span><span><strong>${labels[key]}</strong><small>${({equipment:'Acquérir les moyens de produire.',working_capital:'Soutenir votre cycle d’exploitation.',development:'Faire grandir votre activité.',personal_project:'Préparer une étape de votre vie.',housing:'Aménager votre lieu de vie.',education:'Investir dans votre formation.'})[key]}</small></span></label>`).join('')}</div><button type="submit" class="primary">Commencer ma demande →</button><p class="fine-print">Ces catégories décrivent votre projet. Elles ne constituent pas des offres de prêt.</p></form></div><aside class="choice-photo"><img src="assets/${business?'entrepreneur':'workspace'}.jpg" alt="${business?'Une entrepreneuse dans sa boutique':'Un professionnel préparant un projet'}"><div><span class="glass-label">À votre rythme.</span><h2>Votre histoire mérite<br>un projet bien préparé.</h2><p>Une étape après l’autre.<br>Des informations claires, du début à la suite.</p></div></aside></div>`;
$('#choice-form').onsubmit=e=>{e.preventDefault();creditProfile=$('#choice-profile').value;creditProduct=new FormData(e.target).get('product');draft=M.create(creditCore,creditProfile,creditProduct);route('demande/0')};document.querySelectorAll('[data-core]').forEach(b=>b.onclick=()=>{creditCore=b.dataset.core;creditProfile=creditCore==='businesses'?'reconstructed_cashflows':'employee';creditProduct=creditCore==='businesses'?'equipment':'personal_project';choose();bindCommon()})}
function periodTable(){const individual=draft.core==='individuals';const columns=individual?[['income','Revenu net'],['essential','Dépenses essentielles'],['deductions','Retenues crédit']]:[['receipts','Encaissements'],['expenses','Charges d’exploitation'],['taxes','Impôts'],['investments','Investissements essentiels'],['household','Prélèvements ménage'],['disbursement','Crédit reçu'],['uses','Emplois financés']];return `<div class="wide table-scroll entry-table"><table><thead><tr><th>PÉRIODE</th><th>NATURE</th>${columns.map(c=>`<th>${c[1].toUpperCase()}<small>FCFA</small></th>`).join('')}${individual?'<th>SALAIRE ET RETENUES</th>':''}<th></th></tr></thead><tbody>${draft.periods.map((p,i)=>`<tr><td><input type="month" required data-period="${i}" data-key="period" value="${escape(p.period)}" aria-label="Période ${i+1}"></td><td><select data-period="${i}" data-key="basis" aria-label="Nature de la période ${i+1}"><option value="forecast" ${p.basis==='forecast'?'selected':''}>Prévision</option><option value="observed" ${p.basis==='observed'?'selected':''}>Observé</option></select></td>${columns.map(([key,title])=>`<td><input type="number" min="0" step="0.01" inputmode="decimal" data-period="${i}" data-key="${key}" value="${escape(p[key])}" aria-label="${title} période ${i+1}" placeholder="Inconnu"></td>`).join('')}${individual?`<td><select data-period="${i}" data-key="treatment" aria-label="Traitement des retenues période ${i+1}"><option value="unclear" ${p.treatment==='unclear'?'selected':''}>À préciser</option><option value="before_loan_deductions" ${p.treatment==='before_loan_deductions'?'selected':''}>Avant retenues crédit</option><option value="after_loan_deductions" ${p.treatment==='after_loan_deductions'?'selected':''}>Après retenues crédit</option></select></td>`:''}<td><button type="button" class="remove-row" data-remove-period="${i}" aria-label="Retirer la période ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div><div class="wide row-actions"><button class="outline" type="button" id="add-period">＋ Ajouter une période</button></div>`}
function scheduleTable(){return `<div class="wide table-scroll entry-table"><table><thead><tr><th>PÉRIODE</th><th>CAPITAL · FCFA</th><th>INTÉRÊTS · FCFA</th><th>FRAIS · FCFA</th></tr></thead><tbody>${draft.periods.map((p,i)=>`<tr><td>${p.period?month(p.period):'Période à préciser'}</td>${['principal','interest','fees'].map((key,k)=>`<td><input type="number" min="0" step="0.01" data-period="${i}" data-key="${key}" value="${escape(p[key])}" aria-label="${['Capital','Intérêts','Frais'][k]} nouvelle échéance ${i+1}" placeholder="Inconnu"></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="wide fine-print">Saisissez l’échéancier communiqué par le prêteur. Sur les périodes sans échéance, inscrivez explicitement zéro. Le capital total doit correspondre au montant demandé.</p>`}
function debtTable(){return `${draft.debts.length?`<div class="wide table-scroll entry-table"><table><thead><tr><th>RÉFÉRENCE</th><th>PÉRIODE</th><th>CAPITAL</th><th>INTÉRÊTS</th><th>FRAIS</th><th></th></tr></thead><tbody>${draft.debts.map((d,i)=>`<tr>${[['reference','text'],['period','month'],['principal','number'],['interest','number'],['fees','number']].map(([key,type])=>`<td><input type="${type}" ${type==='number'?'min="0" step="0.01"':''} data-debt="${i}" data-key="${key}" aria-label="${key} dette ${i+1}" value="${escape(d[key])}"></td>`).join('')}<td><button type="button" class="remove-row" data-remove-debt="${i}" aria-label="Retirer dette ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="wide empty-inline">Aucune échéance existante renseignée. Si vous avez déjà un crédit, ajoutez chaque échéance comprise dans l’horizon.</p>'}<div class="wide row-actions"><button class="outline" type="button" id="add-debt">＋ Ajouter une échéance existante</button></div>`}
function formScreen(index){if(!draft)return emptyGate('Commencez par votre projet.','Choisissez le type de financement pour ouvrir votre demande.');draft.step=Math.min(Math.max(index||0,0),5);draft.stage='form';const n=draft.step;const individual=draft.core==='individuals';const titles=individual?['Faisons connaissance.','Parlons de votre projet.','Votre quotidien, en chiffres.','Chaque engagement compte.','Vos appuis pour avancer.','Les détails qui éclairent.']:['Votre entreprise, d’abord.','Une ambition bien définie.','Une trésorerie qui se raconte.','Une vision claire de vos dettes.','Au-delà des flux.','Les détails qui éclairent.'];setHeading(titles[n],'','demande');let html='';
if(n===0)html=panel(individual?'Vous et votre ménage':'L’entreprise et son représentant','Seules les informations utiles à votre dossier.',input('name',individual?'Nom du demandeur':'Raison sociale','text','',true)+input('asOf','Date de référence','date','Les données observées doivent être antérieures ou égales à cette date.',true)+input('address','Adresse')+input('telephone','Téléphone','tel')+input('email','Adresse e-mail','email')+input('identityRef','Référence du document d’identité')+(individual?area('householdScope','Périmètre du ménage','Personnes, revenus mobilisables et charges incluses.',true):input('legalForm','Forme juridique')+input('rccm','Référence RCCM')+input('ifu','Référence IFU')+input('representative','Représentant déclaré')+area('activity','Votre activité','Ce que vous produisez ou vendez, et à qui.',true)));
if(n===1)html=panel(labels[draft.product]||'Votre financement','Aucune offre ni condition bancaire n’est présumée.',area('purpose','À quoi servira le financement ?','Décrivez les dépenses prévues.',true)+input('principal','Capital demandé · FCFA','number','Le total des remboursements en capital sera rapproché de ce montant.',true)+input('need','Besoin total justifié · FCFA','number','Laissez vide si inconnu.')+input('contribution','Apport personnel annoncé · FCFA','number','Déclaration, à justifier séparément.')+input('rate','Taux nominal annuel — valeur décimale','number','Exemple : 0,12 pour 12 %. Facultatif ; ne remplace pas l’échéancier.'));
if(n===2)html=panel(individual?'Revenus nets et budget':'Flux directs d’exploitation','Les prévisions doivent être explicites. Faites défiler le tableau pour voir toutes les colonnes.',(individual?input('source','Source du revenu','text',draft.profile==='self_employed'?'Revenu personnel net après coûts professionnels.':'Employeur, caisse de pension ou autre source.')+(draft.profile==='self_employed'?select('professionalCostsConfirmed','Les coûts professionnels nécessaires sont-ils déjà déduits ?',[['no','À préciser'],['yes','Oui, le montant est mon revenu personnel net']]):''):input('openingCash','Trésorerie initiale · FCFA','number','Solde disponible avant la première période.',true))+periodTable());
if(n===3)html=panel('Le nouveau crédit','Renseignez le service de dette exact pour chaque période.',scheduleTable())+panel('Les crédits déjà en cours','La même dette garde la même référence sur ses différentes périodes.',debtTable()+select('historyApplicable','Historique de remboursement disponible ?',[['unknown','À préciser'],['yes','Oui, à documenter'],['no','Pas d’historique déclaré']]));
if(n===4&&individual)html=panel('Votre réserve disponible','Une épargne bloquée ne remplace pas des liquidités mobilisables.',input('reserve','Réserve mobilisable · FCFA','number','Zéro si aucune ; aucun montant n’est supposé disponible.',true)+input('blockedSavings','Épargne bloquée · FCFA','number','Facultatif, distinct de la réserve.')+area('continuity','Continuité et stabilité des revenus','Contrat, ancienneté, saisonnalité ou changements attendus.'))+panel('Historique de revenus','Des observations passées, distinctes de vos prévisions.',`${draft.history.length?`<div class="wide table-scroll entry-table"><table><thead><tr><th>PÉRIODE</th><th>REVENU NET · FCFA</th><th></th></tr></thead><tbody>${draft.history.map((h,i)=>`<tr><td><input type="month" data-history="${i}" data-key="period" value="${escape(h.period)}" aria-label="Historique période ${i+1}"></td><td><input type="number" min="0" step="0.01" data-history="${i}" data-key="amount" value="${escape(h.amount)}" aria-label="Revenu historique ${i+1}"></td><td><button type="button" class="remove-row" data-remove-history="${i}" aria-label="Retirer historique ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div>`:''}<button type="button" class="outline" id="add-history">＋ Ajouter un mois observé</button>`);
if(n===4&&!individual)html=panel('Comptabilité et rentabilité','Les montants comptables ne sont pas assimilés aux encaissements.',select('accountingApplicable','Comptes disponibles ?',[['unknown','À préciser'],['yes','Oui'],['no','Non disponibles']])+(draft.form.accountingApplicable==='yes'?input('accountingStart','Début de l’exercice','date')+input('accountingEnd','Fin de l’exercice','date')+select('unit','Unité des états financiers',[['','À préciser'],['1','FCFA'],['1000','Milliers de FCFA'],['1000000','Millions de FCFA']])+input('turnover','Chiffre d’affaires','number')+input('operatingExpenses','Charges d’exploitation','number'):''))+panel('Cycle d’exploitation','Le BFR est analysé séparément : il n’est pas déduit une seconde fois des flux directs.',select('workingCapital','Données de stocks, créances et fournisseurs ?',[['unknown','À préciser'],['yes','Oui'],['no','Non applicable déclaré']])+(draft.form.workingCapital==='yes'?input('bfrDate','Date du bilan de cycle','date')+input('inventory','Stocks · FCFA','number')+input('receivables','Créances clients · FCFA','number')+input('payables','Dettes fournisseurs · FCFA','number'):''))+panel('Garanties et engagements','Une garantie ne compense pas une capacité de remboursement déficitaire.',select('collateralApplicable','Garantie proposée ?',[['unknown','À préciser'],['yes','Oui'],['no','Aucune garantie déclarée']])+(draft.form.collateralApplicable==='yes'?input('collateralDescription','Description de la garantie')+input('collateralValue','Valeur déclarée · FCFA','number'):'')+input('taxArrears','Arriérés fiscaux · FCFA','number')+input('socialArrears','Arriérés sociaux · FCFA','number')+input('offBalance','Engagements hors bilan · FCFA','number'));
if(n===5)html=panel('Vos hypothèses','Expliquez sur quoi reposent vos prévisions. Une ligne par hypothèse.',area('assumptions','Hypothèses de revenus, charges et calendrier','Aucune croissance ni reconduction ne sera présumée.',true)+area('comments','Précisions complémentaires','Événements à venir, difficultés, points à expliquer.'))+`<div class="calm-note"><strong>La suite : vos justificatifs.</strong><p>Vous pourrez importer les PDF, ajouter des photos de scans, contrôler l’ordre des pages, puis vérifier la cohérence du dossier.</p></div>`;
$('#view').innerHTML=rail('form')+modeNotice()+`<div class="form-layout"><aside class="form-aside"><span class="mini-kicker">${individual?'PARTICULIER':'ENTREPRISE / PME'} · ${escape(labels[draft.product]||'Financement')}</span><ol class="form-step-list" aria-label="Sections du formulaire">${steps(draft).map((s,i)=>`<li class="${i===n?'active':i<n?'done':''}"><button type="button" data-form-step="${i}" ${i===n?'aria-current="step"':''}><b>${i<n?'✓':String(i+1).padStart(2,'0')}</b>${s}</button></li>`).join('')}</ol></aside><form id="journey-form"><div class="form-step-title"><span>ÉTAPE ${n+1} SUR 6</span><button type="button" id="save-draft" class="text-button">Enregistrer le brouillon ↗</button></div>${html}<div class="form-bottom"><button type="button" class="outline" id="previous-step">← ${n?'Précédent':'Choix du crédit'}</button><button type="submit" class="primary">${n===5?'Passer aux documents':'Continuer'} →</button></div></form></div>`;
const form=$('#journey-form');form.oninput=e=>{if(e.target.matches('input,textarea,select')){invalidate();sync(form)}};form.onchange=e=>{sync(form);if(['accountingApplicable','workingCapital','collateralApplicable'].includes(e.target.name))window.renderApp()};form.onsubmit=e=>{e.preventDefault();sync(form);if(!form.reportValidity())return;if(n===5){draft.stage='documents';route('documents')}else route('demande/'+(n+1))};$('#previous-step').onclick=()=>{sync(form);route(n?'demande/'+(n-1):'choix')};$('#save-draft').onclick=async()=>{sync(form);const b=$('#save-draft');b.disabled=true;try{await window.CreditServices.saveDraft(draft);toast('Brouillon enregistré sur le serveur.')}catch(e){toast(e.message)}finally{b.disabled=false}};document.querySelectorAll('[data-form-step]').forEach(b=>b.onclick=()=>{sync(form);route('demande/'+b.dataset.formStep)});
const add=(id,fn)=>{if($(id))$(id).onclick=()=>{sync(form);invalidate();fn();window.renderApp()}};add('#add-period',()=>draft.periods.push(M.blankPeriod()));add('#add-debt',()=>draft.debts.push({reference:'',period:'',principal:'',interest:'',fees:''}));add('#add-history',()=>draft.history.push({period:'',amount:''}));for(const type of ['period','debt','history'])document.querySelectorAll('[data-remove-'+type+']').forEach(b=>b.onclick=()=>{sync(form);invalidate();({period:draft.periods,debt:draft.debts,history:draft.history})[type].splice(Number(b.dataset[{period:'removePeriod',debt:'removeDebt',history:'removeHistory'}[type]]),1);window.renderApp()})}
let appendDocIndex=null;let catalog={};fetch('data/document-catalog.json').then(r=>r.json()).then(c=>{catalog=c;if(location.hash==='#documents')window.renderApp()}).catch(()=>{});
function docNames(id){return catalog[id]?.title||({identity_card:'Pièce d’identité',bank_statement:'Relevés bancaires',payslip:'Bulletin de salaire',rccm:'Registre du commerce',annual_financials:'États financiers',quotation:'Devis fournisseur',pension_statement:'Relevé de pension'})[id]||id.replaceAll('_',' ')}
function suggestedDocs(){return draft.core==='businesses'?['identity_card','rccm','bank_statement','quotation']:['identity_card',draft.profile==='retired'?'pension_statement':draft.profile==='self_employed'?'bank_statement':'payslip','address_proof']}
function docPolicy(id){return policies?.rules[id]?.policy||'unavailable'}
function docPolicyText(id){return ({scan_required:'Scan requis par la politique produit',original_preferred:'Original numérique recommandé',structured_required:'Saisie structurée requise'})[docPolicy(id)]||'Politique serveur indisponible'}
function docsScreen(){if(!draft)return emptyGate('Vos pièces, au bon endroit.','Votre demande détermine les justificatifs à préparer.');draft.stage='documents';setHeading('Les pièces qui donnent du sens.','Vos justificatifs, au bon endroit.','demande');const options=policies?Object.entries(policies.rules).filter(([id,r])=>r.profiles.includes(draft.core)&&r.policy!=='structured_required'&&!['policy','verification'].includes(catalog[id]?.family)).sort((a,b)=>docNames(a[0]).localeCompare(docNames(b[0]),'fr')):suggestedDocs().map(id=>[id,{}]);$('#view').innerHTML=rail('documents')+modeNotice()+`<div class="document-intro"><div><span class="mini-kicker">BIEN PRÉPARER VOS PIÈCES</span><h2>Une image nette.<br>Une information claire.</h2><p>Des pages entières, nettes et lisibles.</p><div class="document-chips">${suggestedDocs().map(id=>`<span>${escape(docNames(id))}</span>`).join('')}</div><small>Repères indicatifs pour ce parcours ; la liste définitive dépendra du prêteur.</small></div><img src="assets/workspace.jpg" alt="Un professionnel préparant ses documents"></div><div class="upload-layout"><section class="form-panel"><h2>Ajouter une pièce</h2><p class="panel-intro">Vous pouvez joindre plusieurs images d’un même document.</p><form id="document-meta"><div class="field-grid"><label class="field wide"><span>Type de document</span><select id="document-type">${options.map(([id])=>`<option value="${id}" ${id==='identity_card'?'selected':''}>${escape(docNames(id))}</option>`).join('')}</select><small id="document-policy"></small></label><label class="field"><span>Période du document</span><input id="document-period" type="month" required value="${draft.periods[0]?.period||''}"></label><label class="field"><span>Rôle dans le dossier</span><input id="document-role" required placeholder="Ex. Revenu personnel" maxlength="120"></label></div><div class="upload-actions"><button class="primary" id="import-files" type="button">＋ Importer un PDF ou des images</button><button class="outline" id="scan-image" type="button">⌗ Photographier un document</button></div><input class="file-input" id="journey-files" type="file" multiple accept="application/pdf,image/png,image/jpeg"><input class="file-input" id="journey-camera" type="file" accept="image/*" capture="environment"><p class="fine-print">JPEG, PNG, PDF · ${policies?format(policies.limits.max_file_bytes/1048576):'—'} Mio par fichier, ${policies?format(policies.limits.max_total_bytes/1048576):'—'} Mio par pièce. Une photo ne certifie pas l’authenticité du document.</p></form></section><aside class="scan-advice"><span class="advice-icon">↗</span><h3>Un document à la fois.</h3><ol><li>Choisissez le type et la période.</li><li>Ajoutez toutes ses pages.</li><li>Vérifiez le cadrage et l’ordre.</li></ol><span class="badge grey">En attente d’envoi</span></aside></div><section><div class="section-head"><h2>Les pièces ajoutées <span>${draft.documents.length}</span></h2></div><div class="local-documents">${draft.documents.length?draft.documents.map((d,i)=>`<article class="uploaded-document"><div class="uploaded-head"><div><span class="mini-kicker">${escape(docPolicyText(d.type))}</span><h3>${escape(docNames(d.type))}</h3><p>${escape(d.period)} · ${escape(d.role)}</p></div><button class="outline small-button" data-add-pages="${i}">Ajouter des pages</button><button class="outline small-button" data-remove-doc="${i}">Retirer cette pièce</button></div><div class="scan-pages">${d.pages.map((p,j)=>`<div class="scan-page">${p.mime==='application/pdf'?`<div class="pdf-tile"><span>PDF</span><strong>${escape(p.name)}</strong><small>Pagination à inspecter sur le serveur</small></div>`:`<div class="scan-image-wrap"><img style="transform:rotate(${p.rotation}deg);clip-path:inset(${p.crop[1]*100}% ${(1-p.crop[2])*100}% ${(1-p.crop[3])*100}% ${p.crop[0]*100}%)" src="${p.url}" alt="Page ${j+1} du document sélectionné"></div>`}<strong>${escape(p.name)}</strong><small>${format(p.size/1024)} Kio · Prêt à envoyer</small><div class="page-tools"><button data-preview="${i}:${j}" aria-label="Prévisualiser ${escape(p.name)}">Voir ↗</button>${p.mime!=='application/pdf'?`<button data-rotate="${i}:${j}" aria-label="Tourner la page ${j+1}">↻</button><button data-crop="${i}:${j}" aria-label="Recadrer la page ${j+1}">⌗</button>`:''}<button data-remove-page="${i}:${j}" aria-label="Retirer la page ${j+1}">×</button><button data-move="${i}:${j}:-1" aria-label="Déplacer la page ${j+1} avant" ${j===0?'disabled':''}>←</button><button data-move="${i}:${j}:1" aria-label="Déplacer la page ${j+1} après" ${j===d.pages.length-1?'disabled':''}>→</button></div></div>`).join('')}</div><div class="upload-states"><span class="badge grey">Dépôt : ${escape(d.status?.deposit_status||'sélection locale')}</span><span class="badge grey">Qualité : ${escape(d.status?.quality_status||'non contrôlée')}</span><span class="badge grey">OCR : ${escape(d.status?.ocr_status||'non exécuté')}</span><span class="badge grey">Revue : ${escape(d.status?.review_status||'en attente')}</span></div></article>`).join(''):'<div class="calm-note"><strong>Ajoutez vos justificatifs.</strong><p></p></div>'}</div></section><div class="form-bottom"><button class="outline" data-route="demande/5">← Revenir aux formulaires</button><button class="primary" data-route="verification">Vérifier ma demande →</button></div>`;
const policyText=()=>$('#document-policy').textContent=docPolicyText($('#document-type').value)+'. Les contrôles techniques ne certifient pas l’authenticité.';policyText();$('#document-type').onchange=policyText;
const chooseFile=id=>{appendDocIndex=null;if(!policies){toast('Connectez-vous pour charger la politique documentaire du serveur.');return}if(!$('#document-meta').reportValidity())return;$(id).click()};$('#import-files').onclick=()=>chooseFile('#journey-files');$('#scan-image').onclick=()=>chooseFile('#journey-camera');$('#journey-files').onchange=e=>acceptFiles(e.target.files);$('#journey-camera').onchange=e=>acceptFiles(e.target.files);
document.querySelectorAll('[data-add-pages]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.addPages),d=draft.documents[i];if(d.remote?.confirmed){toast('La pièce est confirmée ; sa réouverture relève de la revue autorisée.');return}appendDocIndex=i;$('#document-type').value=d.type;$('#document-period').value=d.period;$('#document-role').value=d.role;$('#journey-files').click()});document.querySelectorAll('[data-remove-doc]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.removeDoc);try{await window.CreditServices.removeDocument(draft,draft.documents[i])}catch(e){toast(e.message);return}const d=draft.documents.splice(i,1)[0];await window.CreditServices.saveDraft(draft).catch(e=>toast(e.message));d.pages.forEach(p=>URL.revokeObjectURL(p.url));draft.report=null;draft.reviewState='not_submitted';window.renderApp()});document.querySelectorAll('[data-remove-page]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.removePage.split(':').map(Number);draft.documents[i].pages.splice(j,1);draft.reviewState='not_submitted';window.renderApp()});document.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.rotate.split(':').map(Number);draft.documents[i].pages[j].rotation=(draft.documents[i].pages[j].rotation+90)%360;draft.reviewState='not_submitted';window.renderApp()});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const [i,j,offset]=b.dataset.move.split(':').map(Number);const pages=draft.documents[i].pages;[pages[j],pages[j+offset]]=[pages[j+offset],pages[j]];draft.reviewState='not_submitted';window.renderApp()});document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>cropPage(b.dataset.crop));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.preview.split(':').map(Number);const p=draft.documents[i].pages[j];openModal(`<h2>Aperçu local.</h2><p>${escape(p.name)} · </p>${p.mime==='application/pdf'?`<div class="pdf-preview-card"><span>PDF</span><a class="outline" href="${p.url}" target="_blank" rel="noopener noreferrer">Ouvrir ce PDF ↗</a></div>`:`<img class="local-preview" src="${p.url}" alt="Aperçu du scan" style="transform:rotate(${p.rotation}deg)">`}`,'VOTRE DOCUMENT')})}
async function acceptFiles(files){if(busy||!files?.length)return;const currentDraft=draft;const type=$('#document-type').value,period=$('#document-period').value,role=$('#document-role').value.trim();busy=true;const pages=[];try{let total=0;for(const file of files){if(file.size>policies.limits.max_file_bytes)throw new Error('Le fichier dépasse la limite du serveur.');total+=file.size;if(total>policies.limits.max_total_bytes)throw new Error('La pièce dépasse la limite cumulée du serveur.');const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());let mime=bytes[0]===0xff&&bytes[1]===0xd8?'image/jpeg':bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71?'image/png':String.fromCharCode(...bytes.slice(0,5))==='%PDF-'?'application/pdf':null;if(!mime)throw new Error('Format non reconnu. Choisissez un PDF, JPEG ou PNG.');const url=URL.createObjectURL(file);revocation.push(url);if(mime!=='application/pdf'){const size=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve([im.naturalWidth,im.naturalHeight]);im.onerror=()=>reject(new Error('Image illisible.'));im.src=url});if(size[0]*size[1]>policies.limits.max_pixels)throw new Error('L’image dépasse la limite de pixels du serveur.');if(size[0]<100||size[1]<100)throw new Error('Image trop petite : choisissez une photo plus lisible.')}pages.push({name:file.name,size:file.size,mime,url,rotation:0,crop:[0,0,1,1],file})}if(pages.length>policies.limits.max_pages)throw new Error('Trop de pages pour cette pièce.');invalidate();if(appendDocIndex!==null)currentDraft.documents[appendDocIndex].pages.push(...pages);else currentDraft.documents.push({type,period,role,pages});appendDocIndex=null;currentDraft.reviewState='not_submitted';currentDraft.report=null;window.renderApp();await window.CreditServices.stageDocuments(currentDraft);window.renderApp();toast('Original conservé sur le serveur. Contrôlez les pages avant confirmation.')}catch(e){pages.forEach(p=>URL.revokeObjectURL(p.url));toast(e.message)}finally{busy=false}}
function verification(){if(!draft)return emptyGate('Votre demande, étape par étape.','Commencez par choisir votre financement.');draft.stage='verification';const issues=M.validate(draft);const hasDocs=draft.documents.length>0;setHeading('Tout relire. Puis avancer.','Les dernières vérifications avant l’envoi.','demande');$('#view').innerHTML=rail('verification')+modeNotice()+`<div class="verification-layout"><section><div class="verification-card"><span class="mini-kicker">VOTRE DEMANDE</span><h2>${issues.length?'Quelques points à préciser.':'Votre saisie est cohérente.'}</h2>${issues.length?`<ul class="issue-list">${issues.map(e=>`<li><span>!</span><span>${escape(e.text)}</span><button class="text-button" data-route="demande/${e.step}">Corriger ↗</button></li>`).join('')}</ul>`:'<div class="check-line"><span>✓</span> Montants, échéances et périodes rapprochés.</div>'}<div class="summary-grid"><div><small>Demandeur</small><strong>${escape(draft.form.name||'À renseigner')}</strong></div><div><small>Projet</small><strong>${escape(labels[draft.product]||'Financement')}</strong></div><div><small>Capital</small><strong>${format(draft.form.principal||null)} FCFA</strong></div><div><small>Périodes</small><strong>${draft.periods.length}</strong></div></div></div><div class="verification-card"><span class="mini-kicker">VOS DOCUMENTS</span><h2>${draft.documents.length} pièce(s) à transmettre.</h2><div class="review-states"><div><span>Lecture des documents</span><small>Après envoi</small></div><div><span>Vérification des informations</span><small>Par un agent habilité</small></div></div><button class="outline" data-route="documents">Revoir mes pièces ↗</button></div></section><aside><div class="review-summary"><span class="mini-kicker">AVANT L’ENVOI</span><h2>Votre dossier est entre vos mains.</h2><form id="verification-form"><label class="check-field"><input type="checkbox" name="reviewed" required ${draft.confirmations.reviewed?'checked':''}><span>J’ai relu les montants, les périodes et les engagements.</span></label><label class="check-field"><input type="checkbox" name="understood" required ${draft.confirmations.understood?'checked':''}><span>Je confirme que les pièces concernent ma demande.</span></label><button class="primary" type="submit" ${issues.length||!hasDocs?'disabled':''}>Transmettre pour vérification →</button><p id="submission-message" role="status" class="submission-message">${window.CreditServices?.ready?'':'Service d’envoi non connecté. Votre dossier reste sur cette page.'}</p></form><button class="text-button" id="export-case">Exporter ma saisie ↗</button></div></aside></div>`;$('#verification-form').onsubmit=async e=>{e.preventDefault();if(issues.length||!hasDocs||!e.target.reportValidity())return;const currentDraft=draft;const message=$('#submission-message');const button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='Envoi en cours…';e.target.setAttribute('aria-busy','true');try{if(!window.CreditServices?.ready)throw new Error('Service d’envoi indisponible. Aucun dossier transmis.');currentDraft.confirmations={reviewed:true,understood:true};await window.CreditServices.submitDraft(currentDraft,M.buildPayload(currentDraft));currentDraft.reviewState='awaiting_review';message.textContent='Dossier transmis. La vérification des documents est en attente.';button.textContent='Dossier transmis ✓';}catch(error){message.textContent=error.message||'L’envoi a échoué. Réessayez.';button.disabled=false;button.textContent='Réessayer l’envoi →';}finally{e.target.removeAttribute('aria-busy')}};$('#export-case').onclick=()=>downloadJSON(issues.length?{schema_version:'credit-pme.form-draft.v1',core:draft.core,profile:draft.profile,form:draft.form,periods:draft.periods,debts:draft.debts,missing_information:issues.map(e=>e.text)}:M.buildPayload(draft),'credit-pme-saisie-'+draft.id+'.json')}
function cropPage(key){const [i,j]=key.split(':').map(Number),p=draft.documents[i].pages[j];openModal(`<h2>Garder les bons repères.</h2><p>Le cadrage s’applique à l’image originale, avant rotation. L’original reste conservé dans cette session.</p><img class="local-preview" src="${p.url}" alt="Original du scan à recadrer"><form id="crop-form"><div class="field-grid">${['Bord gauche','Bord haut','Bord droit','Bord bas'].map((label,k)=>`<label class="field"><span>${label} · % de l’image</span><input name="c${k}" type="number" min="0" max="100" step="1" required value="${Math.round(p.crop[k]*100)}"></label>`).join('')}</div><p id="crop-error" role="status"></p><button type="submit" class="primary">Appliquer le cadrage</button></form>`,'PRÉPARER LE SCAN');$('#crop-form').onsubmit=e=>{e.preventDefault();const v=new FormData(e.target);const a=[0,1,2,3].map(k=>Number(v.get('c'+k))/100);if(a[2]-a[0]<.02||a[3]-a[1]<.02){$('#crop-error').textContent='Le cadre doit conserver au moins 2 % de la largeur et de la hauteur.';return}p.crop=a;draft.reviewState='not_submitted';$('#modal').close();window.renderApp()}}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function emptyGate(title,subtitle){setHeading(title,subtitle,'demande');$('#view').innerHTML=`<div class="empty-journey"><img src="assets/entrepreneur.jpg" alt="Une entrepreneuse dans sa boutique"><div><span class="mini-kicker">UN PARCOURS COMPLET</span><h2>Tout commence<br>avec votre projet.</h2><p>Remplissez vos formulaires, préparez les pièces, puis passez à la vérification. Les analyses et suggestions suivent la revue du dossier.</p><button class="primary" data-route="choix">Commencer ma demande →</button></div></div>`}
function availableReport(){return window.CreditServices?.publishedReport||null}
function reportEmpty(){setHeading('Les chiffres, quand ils sont prêts.','Vos résultats seront disponibles après la préparation et la revue de votre dossier.','analysis');$('#view').innerHTML=`${draft?rail('analysis'):''}<div class="empty-analysis"><div><span class="mini-kicker">ANALYSE EN ATTENTE</span><h2>Une lecture précise.<br>Au bon moment.</h2><p>${draft?'Votre saisie n’a pas encore fait l’objet d’une analyse du serveur.':'Commencez une demande, ajoutez les documents puis vérifiez les éléments.'}</p><button class="primary" data-route="${draft?'verification':'choix'}">${draft?'Revenir à ma vérification':'Préparer ma demande'} →</button></div><img src="assets/workspace.jpg" alt="Un professionnel concentré sur son dossier"></div>`}
function dataChart(report){const rows=report.financial_calculations.periods;const values=rows.map(r=>(r.margin_after_credit??r.margin_after_debt)===null|| (r.margin_after_credit??r.margin_after_debt)===undefined?null:Number(r.margin_after_credit??r.margin_after_debt));const max=Math.max(...values.map(Math.abs),1);return `<div class="cash-chart" role="img" aria-label="Marges par période : ${rows.map((r,i)=>month(r.period)+' '+format(values[i])+' FCFA').join(', ')}">${rows.map((r,i)=>`<div class="cash-column"><strong class="${values[i]<0?'negative':''}">${format(values[i])}</strong><div class="cash-track"><i style="height:${values[i]===null?0:Math.max(4,Math.abs(values[i])/max*50)}%;background:${values[i]<0?'#000':'#b9c3a2'};top:${values[i]<0?'50%':'auto'};bottom:${values[i]<0?'auto':'50%'}"></i></div><span>${month(r.period)}</span></div>`).join('')}</div>`}
function analysis(){const report=availableReport();if(!report)return reportEmpty();if(window.CreditServices?.audience==='applicant')return publicAnalysis(report);const business=report.core==='businesses';setHeading('Votre projet, en perspective.','Des résultats expliqués. Des points de vigilance visibles. Une suite plus claire.','analysis');const rows=report.financial_calculations.periods;const deficit=report.financial_risk.period_deficits?.length||0;const first=rows[0]||{};const margin=first.margin_after_credit??first.margin_after_debt;const balance=first.projected_reserve??first.closing_cash;$('#view').innerHTML=rail('analysis')+`<div class="mode-notice"><span class="mode-dot"></span><div><strong>Analyse partagée · ${business?'Entreprise':'Particulier'}</strong><span>${escape(report.engine_version||'')} · ${escape(report.versions?.mode||'')}</span></div></div><section class="analysis-immersive"><div class="analysis-dark"><span class="dark-kicker">${deficit?'DES TENSIONS À COMPRENDRE':'LES FLUX DE VOTRE PROJET'}</span><h2>${deficit?'Voir les tensions.<br>Préparer la suite.':'Des repères clairs.<br>Pour mieux avancer.'}</h2><p>${business?'La rentabilité ne suffit pas à garantir une trésorerie disponible à chaque échéance.':'Les revenus, les charges et les échéances sont rapprochés période par période.'}</p><div class="dark-metrics"><div><small>Marge · ${first.period?month(first.period):'période indisponible'}</small><strong>${format(margin)}<em> FCFA</em></strong></div><div><small>${business?'Trésorerie finale':'Réserve projetée'} · première période</small><strong>${format(balance)}<em> FCFA</em></strong></div></div><span class="dark-tag">${deficit?'Revue approfondie requise':'Résultats conditionnels aux hypothèses'}</span></div><div class="analysis-portrait"><img src="assets/${business?'entrepreneur':'workspace'}.jpg" alt="${business?'Une entrepreneuse au cœur de son activité':'Un professionnel préparant son projet'}"><div class="portrait-note"><span>LES PERSONNES AVANT LES CHIFFRES</span><strong>Un dossier raconte<br>bien plus qu’un montant.</strong></div></div></section><div class="analysis-summary"><div><span class="mini-kicker">CE QUE LE MOTEUR OBSERVE</span><h2>Comprendre l’essentiel.</h2><p>${escape(report.summary)}</p></div><div class="analysis-actions"><button class="primary" data-route="support">Mes pistes pour avancer →</button><button class="outline" id="print-report">Imprimer cette lecture ↗</button></div></div><div class="results-grid"><section class="form-panel chart-panel"><div class="section-head"><div><span class="mini-kicker">PÉRIODE PAR PÉRIODE</span><h2>La marge après crédit.</h2></div><span class="badge ${deficit?'':'green'}">${deficit} période(s) déficitaire(s)</span></div>${dataChart(report)}<p class="fine-print">La marge est le disponible après service de dette. Les montants négatifs restent visibles.</p><div class="table-scroll"><table><thead><tr><th>PÉRIODE</th><th>${business?'ENCAISSEMENTS':'REVENUS NETS'}</th><th>DETTE EXISTANTE</th><th>NOUVEAU CRÉDIT</th><th>MARGE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${month(r.period)}</td><td>${format(r.operating_receipts??r.net_retained_income)}</td><td>${format(r.existing_debt_service)}</td><td>${format(r.new_debt_service)}</td><td class="money">${format(r.margin_after_credit??r.margin_after_debt)}</td></tr>`).join('')}</tbody></table></div></section><aside class="model-card"><span class="mini-kicker">LE RISQUE, AVEC PRÉCISION</span><h2>Dire ce que l’on sait.<br>Et ce qui manque.</h2>${report.engine_version==='financial_analysis_v2'?`<div class="unavailable-row"><span>Score de politique / 100</span><strong>${escape(report.scoring.criteria_score??'Indisponible')}</strong></div><div class="unavailable-row"><span>Qualification conventionnelle</span><strong>${escape(report.scoring.qualification)}</strong></div><div class="unavailable-row"><span>Revue approfondie</span><strong>${report.scoring.mandatory_review?'Requise':'Selon les contrôles recensés'}</strong></div><p>Politique : ${escape(report.scoring.criteria_validation_status)}. Calculs déterministes sur les données fournies. Aucune probabilité de défaut calculée.</p>`:`<div class="unavailable-row"><span>Score par critères · 70 %</span><strong>${escape(report.scoring.criteria_score??'Indisponible')}</strong></div><div class="unavailable-row"><span>Modèle entraîné · 30 %</span><strong>${escape(report.scoring.model_status)}</strong></div><div class="unavailable-row"><span>Score combiné / 100</span><strong>${escape(report.scoring.combined_score??'Indisponible')}</strong></div><div class="unavailable-row"><span>Probabilité de défaut</span><strong>${report.scoring.probability_of_default?escape(JSON.stringify(report.scoring.probability_of_default)):'Non calculée'}</strong></div><p>Critères : ${escape(report.scoring.criteria_status)}. Mode : ${escape(report.scoring.mode)}. Un indice de risque n’est pas une probabilité de défaut.</p>`}<span class="badge grey">Décision du prêteur : non renseignée</span></aside></div><section class="section-explorer"><div class="section-head"><div><span class="mini-kicker">UNE LECTURE COMPLÈTE</span><h2>${report.sections.length} sections. Chaque constat expliqué.</h2></div></div><div class="section-grid">${report.sections.map((s,i)=>`<button class="section-card ${s.status}" data-section="${i}"><div><span class="section-number">${String(i+1).padStart(2,'0')}</span><span class="badge ${s.status==='favorable'?'green':s.status==='incomplet'?'grey':''}">${statusLabels[s.status]}</span></div><h3>${escape(s.title)}</h3><p>${escape(s.explanation)}</p><span class="section-foot">${s.indicators.length} indicateur(s) · ${s.missing_information.length} à préciser <b>↗</b></span></button>`).join('')}</div></section><section class="assumptions-section"><div><span class="mini-kicker">SOURCES & HYPOTHÈSES</span><h2>Une lecture qui reste traçable.</h2></div><details><summary>Voir les hypothèses et les points à compléter <span>＋</span></summary><ul>${report.assumptions.map(a=>`<li>${escape(a)}</li>`).join('')}${report.missing_information.map(a=>`<li><strong>À préciser :</strong> ${escape(a)}</li>`).join('')}</ul><p>Références du dossier : ${report.sources.map(s=>escape(s.source)).join(' · ')}</p></details></section><div class="simulation-banner"><div><span class="mini-kicker">ET SI LES REVENUS BAISSAIENT ?</span><h2>Regarder aussi les scénarios difficiles.</h2><p>Un test de baisse de 20 % des revenus ou encaissements, sans modifier le dossier original.</p></div><button class="outline" id="stress-test">${report._stress?'Revenir au scénario de base':'Voir le scénario −20 %'} ↗</button></div>`;
$('#print-report').onclick=()=>window.CreditServices.print(draft).catch(e=>toast(e.message));document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>sectionDetail(report.sections[Number(b.dataset.section)]));$('#stress-test').disabled=!window.CreditServices.staff;$('#stress-test').onclick=async()=>{try{if(report._stress)await window.CreditServices.loadReport(draft);else await window.CreditServices.simulate();window.renderApp()}catch(e){toast(e.message)}};}
function publicAnalysis(report){setHeading('Votre analyse communiquée.','Résultats autorisés par votre analyste. Aucun accord de crédit.','analysis');const rows=report.financial_calculations.periods;$('#view').innerHTML=rail('analysis')+`<section class="form-panel"><span class="mini-kicker">RÉSULTATS COMMUNIQUÉS</span><h2>Votre budget, période par période.</h2><p>Les règles internes, scores et observations non publiés ne sont pas communiqués.</p><div class="table-scroll"><table><thead><tr><th>PÉRIODE</th><th>MARGE APRÈS DETTE · FCFA</th><th>RÉSERVE / TRÉSORERIE · FCFA</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${month(r.period)}</td><td>${format(r.margin_after_credit??r.margin_after_debt)}</td><td>${format(r.projected_reserve??r.closing_cash)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p>Résultats financiers non communiqués.</p>':''}<button class="primary" data-route="support">Suggestions communiquées →</button><button class="outline" id="print-report">Télécharger le rapport PDF ↗</button></section>`;$('#print-report').onclick=()=>window.CreditServices.print(draft).catch(e=>toast(e.message))}
function sectionDetail(section){openModal(`<span class="badge ${section.status==='favorable'?'green':'grey'}">${statusLabels[section.status]}</span><h2>${escape(section.title)}</h2><p>${escape(section.explanation)}</p>${section.indicators.length?`<h3>Indicateurs et formules</h3><div class="section-indicators">${section.indicators.map(i=>`<div><small>${escape(i.id.replaceAll('_',' '))}${i.period?' · '+month(i.period):''}</small><strong>${format(i.value)} ${escape(i.unit)}</strong><p>${escape(i.formula)}</p>${i.unavailable_reason?`<p>${escape(i.unavailable_reason)}</p>`:''}</div>`).join('')}</div>`:''}${section.alerts.length?'<h3>Points de vigilance</h3><ul>'+section.alerts.map(a=>`<li>${escape(a)}</li>`).join('')+'</ul>':''}${section.missing_information.length?'<h3>Informations à compléter</h3><ul>'+section.missing_information.map(a=>`<li>${escape(a)}</li>`).join('')+'</ul>':''}<details><summary>Règles et données du scénario</summary><ul>${section.rules.map(r=>`<li>${escape(r.explanation)}</li>`).join('')}</ul><p>${section.data_used.length} champ(s) utilisé(s), conservés dans le rapport de référence.</p></details>`,'LECTURE DÉTAILLÉE')}
function support(){const report=availableReport();if(!report)return emptyGate('Un accompagnement qui vous ressemble.','Les suggestions s’appuieront sur les constats de votre analyse.');setHeading('La suite, pas à pas.','Transformez les constats en actions concrètes, avec leurs prérequis et leurs limites.','support');const suggestions=report.suggestions;const done=suggestions.filter(s=>draft?.actions[s.id]).length;$('#view').innerHTML=rail('support')+`<div class="mode-notice"><span class="mode-dot"></span><div><strong>Suggestions partagées</strong><span> </span></div></div><section class="support-hero"><div><span class="mini-kicker">VOTRE PLAN POUR AVANCER</span><h2>Les bons repères.<br>Les prochains pas.</h2><p>Comprendre un point de tension, documenter une hypothèse, explorer une alternative. Une action à la fois.</p><button class="primary" data-route="analysis">Revoir mon analyse ↗</button></div><div class="support-photo"><img src="assets/entrepreneur.jpg" alt="Une entrepreneuse dans sa boutique"><span class="support-floating">Votre projet.<br><strong>Votre rythme.</strong></span></div></section><div class="support-overview"><div><span class="mini-kicker">PLAN D’ACCOMPAGNEMENT</span><h2>${suggestions.length} piste(s) issue(s) de l’analyse.</h2><p>Les tâches cochées indiquent votre progression personnelle ; elles ne valident pas les pièces ou le dossier.</p></div><span class="progress-pill">${done} / ${suggestions.length} action(s) cochée(s)</span></div><div class="suggestion-list">${suggestions.map((s,i)=>`<article class="suggestion-card"><div class="suggestion-index">${String(i+1).padStart(2,'0')}</div><div class="suggestion-body"><div class="suggestion-top"><span class="badge ${s.priority==='haute'?'':'grey'}">Priorité ${s.priority}</span><span class="muted-label">Pour ${escape(({preteur:'le prêteur',analyste:'l’analyste',demandeur:'le demandeur'})[s.recipient]||s.recipient)}</span></div><h3>${escape(s.action)}</h3><p>${escape(s.problem)}</p><details><summary>Pourquoi cette piste et comment avancer <span>＋</span></summary>${(s.triggers||[]).length?'<h4>Ce qui la déclenche</h4><ul>'+(s.triggers||[]).map(t=>`<li>${escape(t)}</li>`).join('')+'</ul>':''}${s.prerequisites.length?'<h4>Prérequis</h4><ul>'+s.prerequisites.map(t=>`<li>${escape(t)}</li>`).join('')+'</ul>':''}${s.evidence_needed.length?'<h4>Justificatifs à réunir</h4><ul>'+s.evidence_needed.map(t=>`<li>${escape(t)}</li>`).join('')+'</ul>':''}<h4>Coûts et limites</h4><ul>${s.costs_and_limits.map(t=>`<li>${escape(t)}</li>`).join('')}</ul>${s.simulated_effect?`<p>Effet simulé : ${escape(s.simulated_effect.status||'à examiner')}. Une simulation n’est pas une promesse de financement.</p>`:''}</details><label class="action-check"><input type="checkbox" data-action="${escape(s.id)}" ${draft?.actions[s.id]?'checked':''}><span>J’ai traité cette action dans mon plan personnel</span></label></div></article>`).join('')||'<div class="calm-note"><strong>Aucune suggestion supplémentaire retournée.</strong><p>Revenez aux informations et hypothèses du rapport.</p></div>'}</div><div class="guidance-grid"><section class="guidance-card"><span>01 · ORGANISER</span><h3>Un dossier plus lisible.</h3><p>Rassemblez les preuves qui permettent d’expliquer les revenus, les coûts et le calendrier.</p><button class="text-button" data-route="documents">Revenir aux documents →</button></section><section class="guidance-card"><span>02 · EXPLIQUER</span><h3>Des hypothèses documentées.</h3><p>Préparez les questions à discuter avec l’analyste, puis comparez les scénarios utiles.</p><button class="text-button" id="questions-guide">Préparer mon échange →</button></section><section class="guidance-card dark"><span>03 · PRENDRE LE TEMPS</span><h3>La décision reste humaine.</h3><p>Ces pistes n’impliquent ni accord de crédit ni réduction garantie du risque.</p><button class="text-button" id="print-plan">Imprimer mon plan ↗</button></section></div>`;
document.querySelectorAll('[data-action]').forEach(el=>el.onchange=()=>{if(draft)draft.actions[el.dataset.action]=el.checked;const n=suggestions.filter(s=>draft?.actions[s.id]).length;$('.progress-pill').textContent=n+' / '+suggestions.length+' action(s) cochée(s)'});$('#print-plan').onclick=()=>window.CreditServices.print(draft,'improvement_plan').catch(e=>toast(e.message));$('#questions-guide').onclick=()=>openModal('<h2>Les questions qui font avancer.</h2><ul><li>Quels justificatifs manquent pour expliquer ma situation ?</li><li>Mes échéances correspondent-elles au calendrier de mes revenus ?</li><li>Quel serait le coût total d’une durée différente ?</li><li>Quelles hypothèses du projet dois-je mieux documenter ?</li></ul><p>Ce guide prépare votre échange. Aucun rendez-vous n’a été demandé.</p>','PRÉPARER SON ÉCHANGE')}
function bindCommon(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>route(b.dataset.route));$('#new-request').onclick=()=>route('choix');if($('#personal-start'))$('#personal-start').onclick=()=>{creditCore='individuals';creditProfile='employee';creditProduct='personal_project';route('choix')};$('#switch-role').onclick=null}
window.renderApp=()=>{if(draft){const existing=requests.find(r=>r.id===draft.id);const row={id:draft.id,name:draft.form.purpose||labels[draft.product]||'Demande en préparation',type:draft.core==='businesses'?'Entreprise':'Particulier',amount:draft.form.principal||'0',date:'Session actuelle',status:draft.reviewState==='awaiting_review'?'En vérification':draft.remote?.id?'Enregistré':'Brouillon',style:'grey',desc:'Brouillon non enregistré.'};if(existing)Object.assign(existing,row);else requests.unshift(row)}if(draft)draftStore.set(draft.id,draft);$('#nav-count').textContent=requests.length;const hash=location.hash.slice(1)||'overview';active=hash;try{if(hash==='overview'||hash==='requests'){renderLegacy();if(hash==='overview'){const progress=$('.progress-banner');if(progress)progress.innerHTML=`<div><span class="mini-kicker">VOTRE PROCHAIN PAS</span><h2>${draft?'Une demande qui prend forme.':'Tout commence avec votre projet.'}</h2></div><button class="outline" data-route="${draft?'demande/'+draft.step:'choix'}">${draft?'Reprendre ma demande':'Préparer ma demande'} →</button>`;const second=$('.stats .stat:nth-child(2)');if(second){const total=requests.reduce((sum,r)=>{try{return sum+M.cents(r.amount)}catch{return sum}},0n);second.innerHTML=`<div class="stat-top"><span>Capital déclaré</span></div><div class="stat-value">${format((total/100n).toString()+'.'+(total%100n).toString().padStart(2,'0'))}<small>FCFA</small></div><div class="stat-note">Vos demandes en préparation</div>`}const third=$('.stats .stat:last-child');if(third)third.innerHTML=`<div class="stat-top"><span>Pièces sélectionnées</span></div><div class="stat-value">${draft?.documents.length||0}<small>pièces</small></div><div class="stat-note">En attente d’envoi</div>`;$('#page-title').textContent='Vos projets. La vie devant.';$('#page-subtitle').textContent='Votre prochain financement commence ici.'}bindCommon();return}if(hash==='choix'){choose()}else if(hash==='demande'||hash.startsWith('demande/'))formScreen(Number(hash.split('/')[1]||draft?.step||0));else if(hash==='documents')docsScreen();else if(hash==='verification')verification();else if(hash==='analysis')analysis();else if(hash==='support')support();else emptyGate('Reprenons votre parcours.','Cette page n’existe pas. Retrouvez les étapes de votre demande.');bindCommon()}catch(error){$('#view').innerHTML='<div class="calm-note"><strong>Cette vue n’a pas pu être affichée.</strong><p>Vos données restent dans cette session. Revenez au choix du crédit ou réessayez.</p><button class="outline" data-route="choix">Revenir au parcours →</button></div>';bindCommon();console.error('Affichage du parcours impossible.')}};
window.addEventListener('hashchange',()=>window.scrollTo(0,0));
const legacyDetail=detail;detail=id=>{if(draftStore.has(id)){draft=draftStore.get(id);window.CreditServices.openDraft(draft).catch(e=>toast(e.message));route('demande/'+draft.step)}else legacyDetail(id)};
window.CreditJourney={getDraft:()=>draft,replaceDraft:d=>{draft=d;draftStore.set(d.id,d)},markDirty:invalidate,getRequestCount:()=>requests.length,setPolicies:p=>{policies=p},clear:()=>{draft=null;draftStore.clear();requests.length=0;revocation.forEach(u=>URL.revokeObjectURL(u));revocation=[]},replaceDrafts:rows=>{draftStore.clear();requests.length=0;draft=null;for(const d of rows){draftStore.set(d.id,d);requests.push({id:d.id,name:d.form.purpose||d.form.name||'Brouillon',type:d.core==='businesses'?'Entreprise':'Particulier',amount:d.form.principal||'0',date:'Enregistré',status:d.remote?.id?'Enregistré':'Brouillon',style:'grey',desc:'Dossier autorisé'})}draft=rows[0]||null}};window.renderApp();
})();
